        }

        var projectError = await CheckProjectAsync(req.ProjectId, req.CourseId, req.ResearchLabId, ct);
        if (projectError is not null)
        {
            return projectError;
        }

        var items = await BuildItemsAsync(req.Items, ct);
        if (items.Error is not null)
        {
