        {
            Id = Guid.NewGuid(),
            RequesterId = caller.UserId,
            CourseId = req.CourseId,
            ResearchLabId = req.ResearchLabId,
            ProjectId = req.ProjectId,
            Notes = NullIfBlank(req.Notes),
            Status = TicketStatus.Pending,
            CreatedAt = now,
            UpdatedAt = now,
        };
